output = []
for ident, disposition, category, priority, reason, fix in records:
    entry = {'id': ident, 'reviewer': '/root', 'disposition': disposition,
             'category': category, 'priority': priority, 'reason': reason}
    if fix:
        entry['proposed_fix_override'] = fix
    output.append(entry)
assert len({entry['id'] for entry in output}) == len(output)
folder = root / 'reconciliation'
folder.mkdir(exist_ok=True)
for start in range(0, len(output), 12):
    path = folder / ('ap-' + str(start // 12 + 1).zfill(2) + '.json')
    content = json.dumps({'reviews': output[start:start + 12]}, indent=2) + '\n'
    assert len(content.encode()) <= 16000
    path.write_text(content)
print(json.dumps({'independently_reconciled_ap_candidates': len(output)}))
